mapper.select:
SELECT percentile_cont(0.25) WITHIN GROUP (ORDER BY price_10k_won / area_sqm) AS p25PricePerSqm,
       percentile_cont(0.5) WITHIN GROUP (ORDER BY price_10k_won / area_sqm) AS medianPricePerSqm,
       percentile_cont(0.75) WITHIN GROUP (ORDER BY price_10k_won / area_sqm) AS p75PricePerSqm,
       COUNT(*) AS comparableCount
FROM trade
WHERE cancel_date IS NULL
  AND share_type IS NULL
  AND property_type = #{propertyType}
  AND sgg_nm = #{sggNm}
  AND bjdong_nm = #{bjdongNm}
  AND area_sqm >= #{areaMin}
  AND area_sqm <= #{areaMax}
  AND build_year >= #{buildYearMin}
  AND build_year <= #{buildYearMax}
  AND contract_date >= #{recencyCutoff}

